def parsear_duracion(s):
    horas, minutos = s.split('h')
    minutos = minutos[:-1]  # Eliminar el 'm' al final
    return int(horas) * 60 + int(minutos)

def buscar(lista, x):
    izquierda, derecha = 0, len(lista) - 1
    while izquierda <= derecha:
        medio = (izquierda + derecha) // 2
        if lista[medio] == x:
            return medio
        elif lista[medio] < x:
            izquierda = medio + 1
        else:
            derecha = medio - 1
    return -1

def agrupar_por(items, clave):
    resultado = {}
    for item in items:
        if item[clave] not in resultado:
            resultado[item[clave]] = []
        resultado[item[clave]].append(item)
    return resultado

def rotar(lista, n):
    if not lista:
        return lista
    n = n % len(lista)  # Manejo de n mayor que el largo de la lista
    if n < 0:
        n += len(lista)  # Manejo de n negativo
    return lista[-n:] + lista[:-n]

def desde_romano(s):
    romanos = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000
    }
    total = 0
    i = 0
    while i < len(s):
        if i + 1 < len(s) and romanos[s[i]] < romanos[s[i + 1]]:
            total += romanos[s[i + 1]] - romanos[s[i]]
            i += 2
        else:
            total += romanos[s[i]]
            i += 1
    return total

def mayor_racha(lista):
    if not lista:
        return None

    max_racha = (None, 0)
    current_racha = (lista[0], 1)

    for i in range(1, len(lista)):
        if lista[i] == current_racha[0]:
            current_racha = (lista[i], current_racha[1] + 1)
        else:
            if current_racha[1] > max_racha[1]:
                max_racha = current_racha
            current_racha = (lista[i], 1)

    if current_racha[1] > max_racha[1]:
        max_racha = current_racha

    return max_racha

