def comprimir(s):
    if len(s) <= 1:
        return s

    compressed = []
    count = 1
    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            count += 1
        else:
            compressed.append(s[i-1] + str(count))
            count = 1

    # Add the last group
    compressed.append(s[-1] + str(count))

    # Join the compressed list into a string
    compressed_str = ''.join(compressed)

    # Compare the original and compressed strings
    if len(compressed_str) < len(s):
        return compressed_str
    else:
        return s

