def contar_islas(grid):
    if not grid or not grid[0]:
        return 0

    rows, cols = len(grid), len(grid[0])
    count = 0

    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols or grid[r][c] == 0:
            return
        grid[r][c] = 0  # Mark as visited
        dfs(r + 1, c)  # Down
        dfs(r - 1, c)  # Up
        dfs(r, c + 1)  # Right
        dfs(r, c - 1)  # Left

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                dfs(r, c)
                count += 1

    return count

def distancia(a, b):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])

    return dp[m][n]

import re

def validar_password(p):
    # Verificar si la contraseña tiene al menos 8 caracteres
    if len(p) < 8:
        return False

    # Verificar si la contraseña contiene al menos una mayúscula
    if not re.search(r'[A-Z]', p):
        return False

    # Verificar si la contraseña contiene al menos una minúscula
    if not re.search(r'[a-z]', p):
        return False

    # Verificar si la contraseña contiene al menos un dígito
    if not re.search(r'\d', p):
        return False

    # Verificar si la contraseña contiene al menos un carácter no alfanumérico
    if not re.search(r'[^a-zA-Z0-9]', p):
        return False

    return True

def a_base(n, base):
    if n == 0:
        return '0'

    digits = '0123456789abcdef'
    result = ''

    while n > 0:
        remainder = n % base
        result = digits[remainder] + result
        n = n // base

    return result

def interseccion(a, b):
    i, j = 0, 0
    result = []
    while i < len(a) and j < len(b):
        if a[i] == b[j]:
            if a[i] not in result:
                result.append(a[i])
            i += 1
            j += 1
        elif a[i] < b[j]:
            i += 1
        else:
            j += 1
    return result

from datetime import datetime

def dias_entre(a, b):
    fecha1 = datetime.strptime(a, '%Y-%m-%d')
    fecha2 = datetime.strptime(b, '%Y-%m-%d')
    delta = fecha2 - fecha1
    return abs(delta.days)

