def titular(s):
    palabras = s.split()
    for i, palabra in enumerate(palabras):
        if i == 0 or palabra.lower() not in ['de', 'del', 'la', 'las', 'el', 'los', 'y']:
            palabras[i] = palabra.capitalize()
    return ' '.join(palabras)

def aplanar_hasta(lista, profundidad):
    if profundidad == 0:
        return lista
    elif profundidad == 1:
        return [item for sublist in lista for item in sublist]
    else:
        return [aplanar_hasta(sublist, profundidad - 1) for sublist in lista]

def sumar_romanos(a, b):
    # Diccionario de valores romanos
    romanos = {
        'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000
    }

    # Convertir los numeros romanos a enteros
    num_a = sum(romanos[letra] for letra in a)
    num_b = sum(romanos[letra] for letra in b)

    # Sumar los numeros
    total = num_a + num_b

    # Función para convertir un entero a romano
    def entero_a_romano(num):
        if num == 0:
            return ""
        for value, symbol in sorted(romanos.items(), reverse=True):
            if num >= value:
                return symbol + entero_a_romano(num - value)

    # Convertir el resultado a romano
    resultado = entero_a_romano(total)

    return resultado

def obtener(d, camino, defecto=None):
    keys = camino.split('.')
    current = d
    for key in keys:
        if key in current:
            current = current[key]
        else:
            return defecto
    return current

def con_reintentos(fn, veces):
    for _ in range(veces):
        try:
            return fn()
        except Exception as e:
            print(f"Intento fallido: {e}")
    raise Exception("Todos los intentos fallaron")
